import * as THREE from 'three';
import { createScene } from './object.js';
import * as fs from 'fs';
import * as path from 'path';

// Create the scene
const root = createScene();

// Apply -90 degree X rotation to convert from Three.js Y-up to Blender Z-up
const rotationMatrix = new THREE.Matrix4();
rotationMatrix.makeRotationX(-Math.PI / 2);

// Update the world matrices
root.updateMatrixWorld(true);

// Collect all geometry data
const vertices = [];
const normals = [];
const faces = [];
let vertexOffset = 0;

function processObject(object) {
  if (object.isMesh) {
    const geometry = object.geometry;
    const worldMatrix = object.matrixWorld.clone();

    // Combine with the rotation matrix for Blender Z-up
    const finalMatrix = rotationMatrix.clone().multiply(worldMatrix);

    // Normal matrix for transforming normals
    const normalMatrix = new THREE.Matrix3().getNormalMatrix(finalMatrix);

    // Get position attribute
    const positionAttr = geometry.getAttribute('position');
    const normalAttr = geometry.getAttribute('normal');
    const index = geometry.getIndex();

    if (object.isInstancedMesh) {
      // Handle InstancedMesh
      const instanceMatrix = new THREE.Matrix4();
      for (let i = 0; i < object.count; i++) {
        object.getMatrixAt(i, instanceMatrix);

        // Combine instance matrix with world matrix
        const combinedMatrix = rotationMatrix.clone()
          .multiply(object.matrixWorld)
          .multiply(instanceMatrix);

        const instanceNormalMatrix = new THREE.Matrix3().getNormalMatrix(combinedMatrix);

        const localVertexOffset = vertices.length;

        // Transform and store vertices
        for (let j = 0; j < positionAttr.count; j++) {
          const vertex = new THREE.Vector3(
            positionAttr.getX(j),
            positionAttr.getY(j),
            positionAttr.getZ(j)
          );
          vertex.applyMatrix4(combinedMatrix);
          vertices.push(vertex);

          if (normalAttr) {
            const normal = new THREE.Vector3(
              normalAttr.getX(j),
              normalAttr.getY(j),
              normalAttr.getZ(j)
            );
            normal.applyMatrix3(instanceNormalMatrix).normalize();
            normals.push(normal);
          }
        }

        // Store faces
        if (index) {
          for (let j = 0; j < index.count; j += 3) {
            faces.push([
              index.getX(j) + localVertexOffset + 1,
              index.getX(j + 1) + localVertexOffset + 1,
              index.getX(j + 2) + localVertexOffset + 1
            ]);
          }
        } else {
          for (let j = 0; j < positionAttr.count; j += 3) {
            faces.push([
              j + localVertexOffset + 1,
              j + 1 + localVertexOffset + 1,
              j + 2 + localVertexOffset + 1
            ]);
          }
        }
      }
    } else {
      // Regular mesh
      const localVertexOffset = vertices.length;

      // Transform and store vertices
      for (let i = 0; i < positionAttr.count; i++) {
        const vertex = new THREE.Vector3(
          positionAttr.getX(i),
          positionAttr.getY(i),
          positionAttr.getZ(i)
        );
        vertex.applyMatrix4(finalMatrix);
        vertices.push(vertex);

        if (normalAttr) {
          const normal = new THREE.Vector3(
            normalAttr.getX(i),
            normalAttr.getY(i),
            normalAttr.getZ(i)
          );
          normal.applyMatrix3(normalMatrix).normalize();
          normals.push(normal);
        }
      }

      // Store faces
      if (index) {
        for (let i = 0; i < index.count; i += 3) {
          faces.push([
            index.getX(i) + localVertexOffset + 1,
            index.getX(i + 1) + localVertexOffset + 1,
            index.getX(i + 2) + localVertexOffset + 1
          ]);
        }
      } else {
        for (let i = 0; i < positionAttr.count; i += 3) {
          faces.push([
            i + localVertexOffset + 1,
            i + 1 + localVertexOffset + 1,
            i + 2 + localVertexOffset + 1
          ]);
        }
      }
    }
  }

  // Process children
  for (const child of object.children) {
    processObject(child);
  }
}

// Process the entire scene
processObject(root);

// Generate OBJ content
let objContent = '# OBJ file exported from Three.js\n';
objContent += '# Converted to Blender Z-up coordinate system\n\n';

// Write vertices
for (const v of vertices) {
  objContent += `v ${v.x.toFixed(6)} ${v.y.toFixed(6)} ${v.z.toFixed(6)}\n`;
}

objContent += '\n';

// Write normals
for (const n of normals) {
  objContent += `vn ${n.x.toFixed(6)} ${n.y.toFixed(6)} ${n.z.toFixed(6)}\n`;
}

objContent += '\n';

// Write faces
const hasNormals = normals.length > 0;
for (const f of faces) {
  if (hasNormals) {
    objContent += `f ${f[0]}//${f[0]} ${f[1]}//${f[1]} ${f[2]}//${f[2]}\n`;
  } else {
    objContent += `f ${f[0]} ${f[1]} ${f[2]}\n`;
  }
}

// Write to file
const outputPath = '/root/output/object.obj';
fs.writeFileSync(outputPath, objContent);

console.log(`OBJ file exported to: ${outputPath}`);
console.log(`Total vertices: ${vertices.length}`);
console.log(`Total faces: ${faces.length}`);

